head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[logger > M > printLog]<br/>WebSquare 엔진의 디버그 로그 배열에 메시지를 추가합니다.",
    "validation" : [
        "message(필수) 파라미터로 디버그 로그 메시지를 문자열로 설정할 수 있어야 합니다.",
        "WebSquare.logEnableFlag 가 false 인 경우 로그가 기록되지 않아야 합니다.",
        "WebSquare.isPrintLog 가 false 인 경우 로그 건수 카운터만 증가하고 실제 메시지는 기록되지 않아야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_printLog_onclick = function () {
    let message = par_message.getValue();

    // printLog 직전 카운터 저장
    var countBefore = WebSquare.logMsgArrayLength;

    WebSquare.logger.printLog(message);

    // printLog 직후 카운터 확인
    var countAfter = WebSquare.logMsgArrayLength;

    // 마지막 로그의 끝부분(message 길이)만 잘라서 비교
    var logArr = WebSquare.logMsgArray;
    var lastLog = (logArr && logArr.length > 0) ? String(logArr[logArr.length - 1]) : "";
    var tailPart = lastLog.slice(-message.length);
    var found = (tailPart === message);

    wf_body_bottom.getObj("scwin").setReturnValue("logEnableFlag : " + WebSquare.logEnableFlag);
    wf_body_bottom.getObj("scwin").setReturnValue("isPrintLog : " + WebSquare.isPrintLog);
    wf_body_bottom.getObj("scwin").setReturnValue("카운터 증가 확인 : " + (countAfter > countBefore ? "PASS" : "FAIL"));
    wf_body_bottom.getObj("scwin").setReturnValue("메시지 일치 확인 : " + (found ? "PASS" : "FAIL"));
}



scwin.btn_toggleLogEnable_onclick = function () {
    WebSquare.logEnableFlag = !WebSquare.logEnableFlag;
    wf_body_bottom.getObj("scwin").setReturnValue("logEnableFlag 변경 : " + WebSquare.logEnableFlag);
}



scwin.btn_toggleIsPrintLog_onclick = function () {
    WebSquare.isPrintLog = !WebSquare.isPrintLog;
    wf_body_bottom.getObj("scwin").setReturnValue("isPrintLog 변경 : " + WebSquare.isPrintLog);
}
